    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    seconds = nanoseconds // 1e9
    microseconds = (nanoseconds % 1e9) // 1e3
    hour = seconds // 3600
    minute = (seconds % 3600) // 60
    second = seconds % 60
    if tz is not None:
        return LocalTime(hour, minute, second, microseconds, tz)
    else:
        return Time(hour, minute, second, microseconds)

