def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.edges[0] or coord > self.edges[-1]:
        return
    index = np.searchsorted(self.edges, coord)
    if index < len(self.values):
        self.values[index] += weight

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.low or coord > self.high:
        raise ValueError("Coordinate is outside the histogram edges")

    bin_index = int((coord - self.low) / self.bin_width)
    if 0 <= bin_index < len(self.values):
        self.values[bin_index] += weight

