def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("The input variable prior must be an InventoryValidator object.")

        if prior.inventory_version != self.inventory_version - 1:
            raise ValueError("The inventory version of the prior must be one less than the current version.")

        # Check if all species and parameters are the same
        if prior.species != self.species:
            raise ValueError("The species in the prior must match the species in the current inventory.")

        if prior.parameters != self.parameters:
            raise ValueError("The parameters in the prior must match the parameters in the current inventory.")

        # Check if the constraints are the same
        if prior.constraints != self.constraints:
