def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    data_dict = {}
    try:
        for root, _, files in os.walk(folder):
            for file in files:
                if file.endswith('.xml'):
                    basename = os.path.splitext(file)[0]
                    if basename not in data_dict:
                        data_dict[basename] = []
                    full_path = os.path.join(root, file)
                    with open(full_path, 'r') as f:
                        data_dict[basename].append(f.read())
    except Exception as e:
        print(f"An error occurred: {e}")
    return data_dict

def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    package_data = {}
    try:
        for root, _, files in os.walk(folder):
            for file in files:
                if file.endswith('.xml'):
                    xml_name = os.path.splitext(file)[0]
                    if xml_name in package_data:
                        package_data[xml_name].append(os.path.join(root, file))
                    else:
                        package_data[xml_name] = [os.path.join(root, file)]
    except Exception as e:
        print(f"An error occurred: {e}")
    return package_data

