def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    package_data = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.filename.endswith('.xml'):
                    # Extract the base name without extension
                    base_name = os.path.splitext(os.path.basename(zinfo.filename))[0]
                    if base_name not in package_data:
                        package_data[base_name] = []
                    package_data[base_name].append(zin.read(zinfo.filename))
    except zipfile.BadZipFile:
        print(f"Error: {zip_path} is not a valid zip file.")
    except FileNotFoundError:
        print(f"Error: {zip_path} does not exist.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    return package_data

