    if not isinstance(self, dict):
        raise ValueError("This method is intended for dict objects only.")

    pretty_str = "{\n"
    for key, value in self.items():
        pretty_str += " " * (indent + 4) + repr(key) + " : "
        if isinstance(value, dict):
            pretty_str += value.pretty(indent + 4, debug)
