        for obj in self._root_hierarchy.values():
            num_objects += 1
            if validate_objects:
                if self._is_valid_object(obj):
                    good_objects += 1
                elif show_warnings:
                    print(f"Warning: Object {obj['id']} is invalid.")

            if check_digests:
                if not self._has_valid_digest(obj):
                    print(f"Error: Object {obj['id']} has an invalid digest.")
                    continue

    except Exception as e:
        print(f"Error during validation: {e}")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for obj in self.storage.iter_objects():
        num_objects += 1
        if validate_objects:
            try:
                obj.validate()
                good_objects += 1
            except Exception as e:
                if show_warnings:
                    warnings.warn(f"Object validation failed: {e}")
        if check_digests:
            try:
                obj.check_digest()
            except Exception as e:
                if show_warnings:
                    warnings.warn(f"Digest check failed for object: {e}")

    return num_objects, good_objects

