def load_configurations(config_filenames: List[str], overrides: Optional[Dict[str, str]] = None, resolve_env: bool = True) -> Tuple[Dict[str, any], List[logging.LogRecord]]:
    configs = {}
    errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config_data = file.read()
                try:
                    if overrides:
                        for key, value in overrides.items():
                            config_data = config_data.replace(f'%({key})', value).replace(f'${{{key}}}', value)
                    if resolve_env:
                        config_data = os.path.expandvars(config_data)
                    parsed_config = yaml.safe_load(config_data)
                    configs[config_filename] = parsed_config
                except yaml.YAMLError as e:
                    error_record = logging.LogRecord(level=logging.ERROR, 
                                                    name='load_configurations', 
                                                    pathname=config_filename, 
                                                    lineno=0, 
                                                    msg=f'Error parsing YAML: {e}', 
                                                    args=(), exc_info=None)
                    errors.append(error_record)
        except FileNotFoundError:
            error_record = logging.LogRecord(level=logging.ERROR, 
                                            name='load_configurations', 
                                            pathname=config_filename, 
                                            lineno=0, 
                                            msg=f'File not found: {config_filename}', 
                                            args=(), exc_info=None)
            errors.append(error_record)

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    parsed_configs = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                raw_config = fd.read()
            if resolve_env:
                raw_config = os.path.expandvars(raw_config)
            config = toml.loads(raw_config) if filename.endswith('.toml') else yaml.safe_load(raw_config)
            if overrides:
                config.update(overrides)
            parsed_configs[filename] = config
        except Exception as e:
            log_record = logging.LogRecord('load_configurations', logging.ERROR, filename, None, (str(e),), None, None)
            log_records.append(log_record)

    return parsed_configs, log_records

